import logging

import triton
import triton.language as tl

from flag_gems.utils import pointwise_dynamic
from flag_gems.utils.codegen_config_utils import CodeGenConfig

logger = logging.getLogger(__name__)

# Wider flats tiles than the shared Ascend default (512 elements / 48 CTAs):
# these kernels are pure streaming workloads and the extra parallelism is what
# closes the gap with the native implementation.  2048-element tiles still fit
# the device's on-chip buffer for one- and two-input kernels.
_OP_CODEGEN_CONFIG = CodeGenConfig(
    max_tile_size=4096,
    max_grid_size=(1024, 1, 1),
    max_num_warps_per_cta=32,
    prefer_block_pointer=False,
    # Match the backend default codegen shape (flat tiles off for Triton 3.x):
    # the multi-dimensional tile path is what overflows the unified buffer.
    prefer_1d_tile=int(triton.__version__[0]) < 3,
)


@pointwise_dynamic(
    is_tensor=[True, True, False],
    promotion_methods=[(0, 1, "DEFAULT")],
    config=_OP_CODEGEN_CONFIG,
)
@triton.jit
def softshrink_backward_kernel(grad_output, self, lambd):
    # PyTorch semantics: grad flows where |self| > lambd; `not (|self| <= lambd)`
    # matches aten's comparison predicate including NaN propagation.
    return tl.where(~(tl.abs(self) <= lambd), grad_output, 0)


def softshrink_backward(grad_output, self, lambd):
    logger.debug("GEMS SOFTSHRINK_BACKWARD")
    grad_input = softshrink_backward_kernel(grad_output, self, lambd)
    return grad_input
